#define CHECK(x) do{auto e=(x);if(e!=cudaSuccess){fprintf(stderr,"CUDA %s\n",cudaGetErrorString(e));exit(10);}}while(0)
struct Case{int h,w,n;float*input,*output;std::vector<float>host;};
int main(){std::vector<double>prefix(2722),gold(11352);FILE*f=fopen("/home/imo/HeCBench_julia/src/doh-julia/fixture.bin","rb");if(!f||fread(prefix.data(),8,prefix.size(),f)!=prefix.size())return 4;fclose(f);f=fopen("/home/imo/HeCBench_julia/src/doh-julia/oracle.bin","rb");if(!f||fread(gold.data(),8,gold.size(),f)!=gold.size())return 5;fclose(f);std::vector<Case>cases;int off=0;for(int ci=0;ci<4;ci++){Case c;c.h=prefix[2710+2*ci];c.w=prefix[2711+2*ci];c.n=c.h*c.w;c.host.assign(c.n+16,-12345.f);for(int i=0;i<c.n;i++)c.host[8+i]=float(prefix[off+c.n+i]);off+=2*c.n;CHECK(cudaMalloc(&c.input,(c.n+16)*4));CHECK(cudaMemcpy(c.input,c.host.data(),c.host.size()*4,cudaMemcpyHostToDevice));CHECK(cudaMalloc(&c.output,(c.n+16)*4));cases.push_back(c);}if(off!=2710)return 6;
auto launch=[](Case&c,float sigma){hessian_matrix_det<<<(c.n+255)/256,256>>>(c.input+8,c.h,c.w,sigma,c.output+8);};for(auto&c:cases)for(int si=0;si<4;si++){launch(c,float(prefix[2718+si]));CHECK(cudaDeviceSynchronize());}
for(int trial=1;trial<=5;trial++){bool ok=true;double seconds=0,err=0,rel=0;std::vector<double>path_times,art=prefix;int go=0;for(auto&c:cases)for(int si=0;si<4;si++){float sigma=prefix[2718+si];std::vector<float>reset(c.n+16,-12345.f);CHECK(cudaMemcpy(c.output,reset.data(),reset.size()*4,cudaMemcpyHostToDevice));auto t=std::chrono::steady_clock::now();for(int rep=0;rep<100;rep++)launch(c,sigma);CHECK(cudaDeviceSynchronize());double dt=std::chrono::duration<double>(std::chrono::steady_clock::now()-t).count()/100;seconds+=dt;path_times.push_back(dt);CHECK(cudaMemcpy(reset.data(),c.output,reset.size()*4,cudaMemcpyDeviceToHost));for(int i=0;i<c.n+16;i++){double got=reset[i],ref=gold[go++],e=fabs(got-ref);if(i<8||i>=c.n+8)ok&=got==ref;else{ok&=std::isfinite(got)&&e<=1.e-4+2.e-6*fabs(ref);err=std::max(err,e);rel=std::max(rel,e/(fabs(ref)+1.e-300));}art.push_back(got);}CHECK(cudaMemcpy(reset.data(),c.input,reset.size()*4,cudaMemcpyDeviceToHost));ok&=memcmp(reset.data(),c.host.data(),reset.size()*4)==0;for(float x:reset){double ref=gold[go++];ok&=double(x)==ref;art.push_back(double(x));}}
if(go!=11352||art.size()!=14074)return 7;std::string path=std::string(getenv("STUDY_OUTPUT_DIR")?getenv("STUDY_OUTPUT_DIR"):".")+"/output_trial"+std::to_string(trial)+".bin";FILE*out=fopen(path.c_str(),"wb");fwrite(art.data(),8,art.size(),out);fclose(out);printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.17g,\"correct\":%s,\"checked_values\":11352,\"max_abs_error\":%.17g,\"max_rel_error\":%.17g,\"timing_region\":\"sum16_box_hessian_kernel_batches_per_repeat\",\"jit_excluded\":true,\"internal_repeats\":100,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"float64\",\"count\":14074,\"byte_order\":\"little\"},\"path_times_seconds\":[",trial,seconds,ok?"true":"false",err,rel,path.c_str());for(int i=0;i<16;i++)printf("%s%.17g",i?",":"",path_times[i]);printf("]}\n");}for(auto&c:cases){cudaFree(c.input);cudaFree(c.output);}}
